// src/utils/Utils.js
const colorDict = {
  "หอม": "orange",       
  "ฝาด": "brown",       
  "ขม": "#818589",         
  "เผ็ด": "red",       
  "เปรี้ยว": "#077A7D",    
  "หวาน": "green",      
  "มัน": "amber",      
  "เค็ม": "blue",       
  "เมา": "purple",     
  "สุขุม": "#6495ED",     
  "จืด": "gray",        
  "เฝื่อน": "darkgray",
  "ร้อน": "darkred"     
};
export function getTasteColor(text) {
     
    if (text ==null || text == "" ){
      return "blue darken-3";
    }
    const key = Object.keys(colorDict).find(k => text.startsWith(k));
    return key ? colorDict[key] + " darken-3" : "blue darken-3"; 
  }
  
  export function getFormattedTaste(text) {
    const keys = [
      "หอม", "ฝาด", "ขม", "เผ็ด", "เปรี้ยว", "หวาน",
      "มัน", "เค็ม", "เมาเบื่อ", "สุขุม", "จืด", "เฝื่อน", "ร้อน"
    ];
  
    const key = keys.find(k => text.startsWith(k));
  
    if (key) {
      const remainingText = text.slice(key.length);
      return remainingText ? `${key} (${remainingText})` : key;
    }
  
    return text; // Return original text if no match
  }

  export {colorDict};