<template>
    <v-container>
        <h2 class="text-h5 font-weight-bold mb-4">
            รสยา → สมุนไพร → ส่วนที่ใช้ → สรรพคุณ
        </h2>

        <!-- Filter Section -->
        <v-row align="center">
            <v-col cols="3">

                <v-btn
                    icon
                    @click="toggleSortOrder"
                    :title="sortOrder === 'asc' ? 'เรียง A → Z' : 'เรียง Z → A'"
                >
                    <v-icon>{{ sortOrder === 'asc' ? 'mdi-arrow-up' : 'mdi-arrow-down' }}</v-icon>
                </v-btn>
                <span class="ml-2">
                    เรียงลำดับชื่อสมุนไพร ({{ sortOrder === 'asc' ? 'ก → ฮ' : 'ฮ → ก' }})
                </span>

            </v-col>
            <v-col cols="3">
                <v-btn
                    color="primary"
                    @click="exportToPDF"
                >
                    <v-icon left>mdi-file-pdf-box</v-icon>
                    pdf
                </v-btn>
            </v-col>
            <v-col cols="3">
                <v-combobox
                    :items="tasteList"
                    label="เลือกรสยา"
                    v-model="selectedTaste"
                ></v-combobox>
            </v-col>
            <v-col cols="3">
                <v-select
                    :items="['prefix', 'present']"
                    label="โหมดการค้นหา"
                    v-model="matchMode"
                ></v-select>
            </v-col>
        </v-row>



        <!-- Display Grouped Herbs -->
        <v-expansion-panels multiple>
            <v-expansion-panel
                v-for="(herbs, taste) in groupedByTaste"
                :key="taste"
            >
                <v-expansion-panel-header>
                    {{ taste }} ({{ herbs.length }} รายการ)
                </v-expansion-panel-header>
                <v-expansion-panel-content>
                    <div class="pl-4 text-left">
                        <div
                            v-for="(herb, index) in herbs"
                            :key="index"
                            class="mb-4"
                        >
                            <strong>{{ herb.name }} ({{ herb.type }}, {{ herb.page }})</strong>
                            <div
                                v-for="(part, i) in herb.parts"
                                :key="i"
                                class="ml-4"
                            >
                                → <strong>{{ part.part }}</strong>
                                <span v-if="part.taste">
                                    (<span v-html="highlightAllTastes(part.taste)"></span>)
                                </span>
                                → <span v-html="highlightBenefits(part.benefits.join(', '))"></span>
                            </div>
                        </div>
                    </div>
                </v-expansion-panel-content>
            </v-expansion-panel>
        </v-expansion-panels>
        <div
            id="pdf-content"
            style="display: none"
        >
            <div
                v-for="(herbs, taste) in groupedByTaste"
                :key="taste"
            >
                <h2>รส "{{ taste }}"</h2>
                <div
                    v-for="(herb, index) in herbs"
                    :key="index"
                    style="margin-bottom: 1em; page-break-inside: avoid;"
                >
                    <h3>{{ index + 1 }}. {{ herb.name }} ({{herb.type}},{{herb.page}})</h3>
                    <div
                        v-for="(part, i) in herb.parts"
                        :key="i"
                    >
                        <strong>→ {{ part.part }} ({{ part.taste }})</strong>:
                        <span v-html="highlightBenefits(part.benefits.join(', '))"></span>
                            
                    </div>
                    <hr style="border: 1px dashed brown;">
                </div>
                <div style="page-break-after: always;"></div>
            </div>
        </div>


    </v-container>

</template>

<script>

import html2pdf from 'html2pdf.js';


export default {
    name: 'TasteGroupView',
    props: {
        plants: {
            type: Array,
            required: true
        }
    },
    data()
    {
        return {
            highlightTerms: [
                'แก้', 'บำรุง', 'ขับ', 'กระตุ้น', 'ทำให้', 'สมาน',
                'กัด', 'ฆ่า', 'ช่วย', 'ถอน', 'ระงับ', 'กล่อม',
                'ระบาย', 'ดับ', 'เป็น', 'เจริญ', 'ให้', 'ถ่าย', 'กระจาย',
                'ชู', 'ลดความ','ลดไข้', 'เพิ่ม', 'กล่อม'
            ],
            tasteList: ['ฝาด', 'ขม', 'หอมเย็น', 'เผ็ดร้อน', 'เปรี้ยว', 'หวาน', 'มัน', 'เค็ม', 'เมาเบื่อ', 'ขื่น', 'ไม่ระบุ'],
            selectedTaste: 'ขม',
            matchMode: 'prefix',
            sortOrder: 'asc'
        }
    },
    computed: {
        groupedByTaste()
        {
            const result = {}

            this.plants.forEach(plant =>
            {
                const matchingParts = plant.parts.filter(part =>
                {
                    if (!part.taste) return false
                    return this.matchMode === 'prefix'
                        ? part.taste.startsWith(this.selectedTaste)
                        : part.taste.includes(this.selectedTaste)
                })

                if (matchingParts.length > 0)
                {
                    if (!result[this.selectedTaste]) result[this.selectedTaste] = []
                    result[this.selectedTaste].push({
                        name: plant.name,
                        page: plant.page,
                        type: plant.type,
                        parts: matchingParts
                    })
                }
            })

            // Sort herb names
            if (result[this.selectedTaste])
            {
                result[this.selectedTaste].sort((a, b) =>
                {
                    const nameA = a.name.toLowerCase()
                    const nameB = b.name.toLowerCase()
                    return this.sortOrder === 'asc'
                        ? nameA.localeCompare(nameB)
                        : nameB.localeCompare(nameA)
                })
            }

            return result
        }
    },
    methods: {
        exportToPDF()
        {
            const element = document.getElementById("pdf-content");
            element.style.display = "block";

            const opt = {
                margin: 0.5,
                filename: 'herbs.pdf',
                image: { type: 'jpeg', quality: 0.98 },
                html2canvas: { scale: 2 },
                jsPDF: { unit: 'in', format: 'a4', orientation: 'portrait' }
            };

            html2pdf().set(opt).from(element).save().then(() =>
            {
                element.style.display = "none";
            });
        },



        toggleSortOrder()
        {
            this.sortOrder = this.sortOrder === 'asc' ? 'desc' : 'asc'
        },
        highlightAllTastes(tasteText)
        {
            if (!tasteText || !this.selectedTaste) return tasteText
            const regex = new RegExp(`(${this.selectedTaste})`, 'g')
            return tasteText.replace(regex, '<strong style="font-weight: bold; color: #398211;">$1</strong>')
        },
        highlightBenefits(benefitsText)
        {
            if (!benefitsText) return benefitsText

            let highlightedText = benefitsText
            this.highlightTerms.forEach(term =>
            {
                const regex = new RegExp(`(${term})`, 'g')
                highlightedText = highlightedText.replace(regex, '<strong style="font-weight: bold; color: #942408;">$1</strong>')
            })
            return highlightedText
        }
    }
}
</script>

<style scoped>
.text-left {
    text-align: left;
}

.highlight {
    font-weight: bold;
    color: #398211;
    /* Green for taste */
}
</style>