<!-- eslint-disable vue/no-mutating-props -->
 <template>
  <v-dialog v-model="isVisible" max-width="400px">
    <v-card>
      <v-card-title class="text-center">คำเตือน</v-card-title>

      <v-img
        class="mx-auto mb-3"
        :src="icon"
        alt="Thai Pharmacist Icon"
        contain
        height="120"
      ></v-img>

      <v-card-text class="text-center" v-html="message"></v-card-text>

      <v-card-actions>
        <v-spacer></v-spacer>
        <!-- Conditional buttons -->
        <template v-if="confirmMode">
          <v-btn text color="red" @click="onCancel">ยกเลิก</v-btn>
          <v-btn text color="green" @click="onConfirm">ยืนยัน</v-btn>
        </template>
        <template v-else>
          <v-btn text @click="closeDialog">ปิด</v-btn>
        </template>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
export default {
  props: {
    isVisible: {
      type: Boolean,
      required: true
    },
    message: {
      type: String,
      required: true
    },
    icon: {
      type: String,
      required: true
    },
    confirmMode: {
      type: Boolean,
      default: false // default is old behavior (OK-only)
    }
  },
  methods: {
    closeDialog() {
      this.$emit('update:isVisible', false);
    },
    onConfirm() {
      this.$emit('confirm'); // new event
      this.closeDialog();
    },
    onCancel() {
      this.$emit('cancel'); // new event
      this.closeDialog();
    }
  }
};
</script>
