                {{ showBack ? '🔄 กลับด้านหน้า' : '🔄 กลับด้านหลังทั้งหมด' }}
              </v-btn>

            </div>
      
            <v-container fluid>
  <v-row>
    <!-- Name Chips Section -->
    <v-col cols="3">
      <div class="d-flex align-center">
        <strong class="mr-2">ชื่อ</strong>
        <v-slide-group
          class="flex-grow-1"
          show-arrows
          style="overflow-x: auto; white-space: nowrap;"
        >
          <v-slide-item
            v-for="chip in nameChips"
            :key="'name-' + chip"
          >
            <v-chip
              class="ma-1"
              @click="addChipToSearch(chip, 'name')"
              color="primary"
              outlined
            >
              {{ chip }}
            </v-chip>
          </v-slide-item>
        </v-slide-group>
      </div>
    </v-col>

    <!-- Taste Chips Section -->
    <v-col cols="7">
      <div class="d-flex align-center">
        <strong class="mr-2">รส</strong>
        <v-slide-group
          class="flex-grow-1"
          show-arrows
          style="overflow-x: auto; white-space: nowrap;"
        >
          <v-slide-item
            v-for="chip in tasteChips"
            :key="'taste-' + chip"
          >
            <v-chip
              class="ma-1"
              @click="addChipToSearch(chip, 'taste')"
              color="green"
              outlined
            >
              {{ chip }}
            </v-chip>
          </v-slide-item>
        </v-slide-group>
      </div>
    </v-col>
  </v-row>
</v-container>


            <!-- Chip Buttons for Benefits -->
            <div class="chip-container">
              <button
                v-for="chip in benefitsChips"
                :key="chip"
                @click="addChipToSearch(chip, 'benefits')"
                class="chip-benefit"
              >
                {{ chip }}
              </button>
            </div>

            <!-- Search Textbox -->
            <v-text-field
              v-model="searchQuery"
              @input="updateSearchCriteriaFromQuery"
              label="ค้นหาสมุนไพร..."
              outlined
              dense
              class="ma-5"
            >
              <template v-slot:prepend-inner>
                <div>
                  <img
                    :src="icons.general.thinking"
                    alt="Search Icon"
                    class="search-img"
                  />
                </div>
              </template>
            </v-text-field>

            <button
              v-if="searchQuery"
              @click="clearSearch"
              class="clear-btn"
            >❌</button>



            <!-- Displaying Filtered Plants -->
            <div class="flashcards">
              <PlantFlashCard
                v-for="(plant, index) in filteredPlants"
                :key="index"
                :plant="plant"
                :searchCriteria="searchCriteria"
                :showBack="showBack"
              />
            </div>
          </div>

          <!-- Displaying Hermits if the active view is 'hermits' -->
          <div
            class="flashcards"
            v-if="activeView === 'hermits'"
          >
            <HermitFlashCard
              v-for="(hermit, index) in hermits"
              :key="index"
              :hermit="hermit"
            />
          </div>

          <!-- Displaying Formulas -->
          <div v-if="activeView === 'formulas'">
            <FormulaTable
              :plants="plants"
              :benefits="benefits"
              :icons="icons"
              @delete-plant="handlePlantDeletion"
            />

          </div>

          <!-- Display Benefit View -->
          <div v-if="activeView === 'benefits'">
            <benefit-table
              :benefits="benefits"
              :icons="icons"
            />
          </div>
          <!-- Display Taste View -->
          <div v-if="activeView === 'tastes'">
            <taste-group-view :plants="plants" />

          </div>

          <author-dialog
            :isVisible="authorDialogVisible"
            @update:isVisible="authorDialogVisible = $event"
            :icons="icons"
          />

          <about-dialog
