<script>
import PlantFlashCard from "./components/PlantFlashCard.vue";
import HermitFlashCard from "./components/HermitFlashCard.vue";
import FormulaTable from "./components/FormulaTable.vue";
import BenefitTable from "./components/BenefitTable.vue";
import AuthorDialog from "./components/AuthorDialog.vue";
import AboutDialog from "./components/AboutDialog.vue";
import TasteGroupView from "./components/TasteGroupView.vue";
import ImportDataButton from "@/components/ImportDataButton.vue";
export default {
  components: {
    PlantFlashCard,
    HermitFlashCard,
    FormulaTable,
    BenefitTable,
    AuthorDialog,
    AboutDialog,
    TasteGroupView,
    ImportDataButton,
  },
  data()
  {
    return {
      baseUrl: process.env.NODE_ENV === "production" ? "/ttm-app" : "",
      isLoading: true, // Add this
      icons: {
        general: null,
        icons: null
      },
      sortDirection: '',  // '', 'asc', or 'desc'

      authorDialogVisible: false,
      aboutDialogVisible: false,
      benifits: [],
      showBack: false,
      plants: [],
      hermits: [],
      activeView: "plants",
      searchQuery: "",
      types: ["ต้น", "เถ้า", "หัว", "ผัก", "หญ้า"],
      nameChips: ["*", "กระ", "กำ", "โกฐ"],
      tasteChips: ["*", "ฝาด", "ขม", "หอมเย็น", "เปรี้ยว", "หวาน", "มัน", "เค็ม", "เมาเบื่อ", "ขื่น", "จืด"],
      benefitsChips: ["*", "บำรุง", "ลม", "กระดูก", "แก้", "กระษัย", "สมาน", "ขับเหงื่อ"],
      searchCriteria: {
        name: "*",
        taste: "*",
        benefits: "*"
      }
    };
  },
  computed: {

    filteredPlants()
    {
      const { name, taste, benefits } = this.searchCriteria;

      let filtered = this.plants.filter(plant =>
      {
        const matchesName = (name === "*" || plant.name.toLowerCase().includes(name.toLowerCase()));
        const matchesTasteAndBenefits = plant.parts.some(part =>
        {
          const matchesTaste = (taste === "*" || part.taste.toLowerCase().includes(taste.toLowerCase()));
          const matchesBenefits = (benefits === "*" || part.benefits.some(benefit => benefit.toLowerCase().includes(benefits.toLowerCase())));
          return matchesTaste && matchesBenefits;
        });

        return matchesName && matchesTasteAndBenefits;
      });

      if (this.sortDirection === 'asc')
      {
        filtered.sort((a, b) => a.name.localeCompare(b.name, 'th'));
      } else if (this.sortDirection === 'desc')
      {
        filtered.sort((a, b) => b.name.localeCompare(a.name, 'th'));
      }

      return filtered;
    }
  }
  ,
  methods: {
    toggleShowBack()
    {
      this.showBack = !this.showBack;
    },
    debounce(fn, delay)
    {
      let timeout;
      return function (...args)
      {
        clearTimeout(timeout);
        timeout = setTimeout(() => fn.apply(this, args), delay);
      };
    },
    checkDuplicateNames()
    {
      const nameCounts = {};
      const duplicates = [];

      this.plants.forEach(plant =>
      {
        const name = plant.name.trim();
        if (name in nameCounts)
        {
          nameCounts[name]++;
        } else
        {
          nameCounts[name] = 1;
        }
      });

      for (const name in nameCounts)
      {
        if (nameCounts[name] > 1)
        {
          duplicates.push({ name, count: nameCounts[name] });
        }
      }

      if (duplicates.length > 0)
      {
        console.warn("🔁 พบชื่อสมุนไพรซ้ำ:", duplicates);
      } else
      {
        console.log("✅ ไม่พบชื่อสมุนไพรซ้ำ");
      }
    }
    ,
    handlePlantDeletion(name)
    {
      const index = this.plants.findIndex(p => p.name === name);
      if (index !== -1)
      {
        this.plants.splice(index, 1);
        console.log("Plant deleted:");

        console.log(this.plants[0]);
      }
    },
    exportFile()
    {
      const processedPlants = this.plants.map(plant =>
      {
        // Clone the plant object to avoid mutating the original
        const cleanedPlant = { ...plant };

        // Remove image
        delete cleanedPlant.image;

        // Add note if missing
        if (!cleanedPlant.note)
        {
          cleanedPlant.note = "";
        }

        // Add family if missing
        if (!cleanedPlant.family)
        {
          cleanedPlant.family = "";
        }

        // Add Page if missing
        if (!cleanedPlant.page)
        {
          cleanedPlant.page = ""
        }
        if(cleanedPlant.type =="" && (cleanedPlant.page >0 && cleanedPlant.page <57)){
          cleanedPlant.type="ต้น";
        }
        if(cleanedPlant.type=="เถ้า"){
          cleanedPlant.type=="เถา";
        }

      

        return cleanedPlant;
      });

      const data = {
        body_systems: this.body_systems,
        icons: this.icons,
        hermits: this.hermits,
        organs: this.organs,
        plants: processedPlants
      };

      const json = JSON.stringify(data, null, 2);
      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const fileName = prompt("กรุณาตั้งชื่อไฟล์ (เช่น plants.json):", "plants.json");

      if (fileName)
      {
        link.href = url;
        link.download = fileName;
        link.click();
        URL.revokeObjectURL(url);
      }
    },

    exportBenefits()
    {
      var data = this.benefits;
      const json = JSON.stringify(data, null, 2);
      const blob = new Blob([json], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const fileName = prompt("กรุณาตั้งชื่อไฟล์ (เช่น benefits.json):", "benefit.json");

      if (fileName)
      {
        link.href = url;
        link.download = fileName;
        link.click();
        URL.revokeObjectURL(url);
      }
    },
    listAllBenefits()
    {
      var result = [
        ...new Set(
          this.plants.flatMap(plant =>
            plant.parts.flatMap(part => part.benefits)
          )
        ),
      ];
      return result;


    },
    addChipToSearch(chip, type)
    {
      // Set the corresponding search criterion based on the chip type
      this.searchCriteria[type] = chip;
      this.updateSearchQuery();
    },
    updateSearchQuery()
    {
      // Update the search query based on the selected chips
      const { name, taste, benefits } = this.searchCriteria;
      this.searchQuery = `${name !== "*" ? name : ""} ${taste !== "*" ? taste : ""} ${benefits !== "*" ? benefits : ""}`.trim();
    },
    updateSearchCriteriaFromQuery()
    {
      // Split search query into parts and update the search criteria
      const queryParts = this.searchQuery.trim().split(" ");
      this.searchCriteria.name = queryParts[0] || "*";
      this.searchCriteria.taste = queryParts[1] || "*";
      this.searchCriteria.benefits = queryParts[2] || "*";
    },
    clearSearch()
    {
      this.searchQuery = "";
      this.searchCriteria = { name: "*", taste: "*", benefits: "*" };
    },
    async loadHerbsData()
    {
      try
      {
        let baseUrl = process.env.NODE_ENV === "production" ? "/ttm-app" : "";
        let url = `${baseUrl}/data.json`;

        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch data: ${response.statusText}`);

        const data = await response.json();

        // Update plant image paths
        data.plants.forEach(plant =>
        {
          plant.image = `${baseUrl}/img/plants/${plant.name}.jpg`;
        });

        // Update general icons correctly
        Object.keys(data.icons.general).forEach(key =>
        {
          data.icons.general[key] = `${baseUrl}/img/icons/${key}.png`;
        });

        // Update part icons correctly
        Object.keys(data.icons.parts).forEach(key =>
        {
          data.icons.parts[key] = `${baseUrl}/img/parts/part_${key}.png`;
        });

        // Preload Hermit images dynamically
        data.hermits.forEach(hermit =>
        {
          let hermitFolder = `${baseUrl}/img/hermits/${hermit.name}`;
          hermit.images = Array.from({ length: 2 }, (_, i) => `${hermitFolder}/pic${i + 1}.jpg`);
        });

        this.icons = data.icons;
        this.plants = data.plants;
        this.hermits = data.hermits;
        this.benefits = this.listAllBenefits();
        this.body_systems = data.body_systems;
        this.organs = data.organs;



      } catch (error)
      {
        console.error("Error loading data:", error);
      }
    },
    async waitForHerbsData()
    {
      while (!this.plants || this.plants.length === 0)
      {
        await new Promise(resolve => setTimeout(resolve, 100)); // Wait 100ms before checking again
      }


    },
    openAuthorDialog()
    {
      this.authorDialogVisible = true;
    },
    openAboutDialog()
    {
      this.aboutDialogVisible = true;
    },
    logPlantData()
    {
      this.plants.forEach(plant =>
      {
        plant.parts.forEach(part =>
        {
          if (!part.taste)
          {
            console.log(`${plant.name} - ${part.name} is missing taste`);
          }
          if (!part.benefits)
          {
            console.log(`${plant.name} - ${part.name} is missing benefits`);
          }
        });
      });
    },
    detectPartsWithoutBenefits()
    {
      const partsWithoutBenefits = [];

      this.plants.forEach(plant =>
      {
        if (Array.isArray(plant.parts))
        {
          plant.parts.forEach(part =>
          {
            if (!Array.isArray(part.benefits) || part.benefits.length === 0)
            {
              partsWithoutBenefits.push({
                plantName: plant.name,
                partName: part.part || 'ไม่ระบุ',
              });
            }
          });
        }
      });

      console.log('Parts missing benefits:', partsWithoutBenefits);
      return partsWithoutBenefits;
    },
    triggerImport()
    {
      this.$refs.importBtn.openDialog();
    },
    handleImportedData(data)
    {
      this.isLoading = true;

      setTimeout(() =>
      {
        // 1. Update image paths
        if (Array.isArray(data.plants))
        {
          data.plants.forEach((p) =>
          {
            if (p.image && !p.image.startsWith("assets/"))
            {
              p.image = "assets/plants/" + p.image;
            }
          });
        }

        if (Array.isArray(data.hermits))
        {
          data.hermits.forEach((h) =>
          {
            if (h.image && !h.image.startsWith("assets/"))
            {
              h.image = "assets/hermits/" + h.image;
            }
          });
        }

        if (Array.isArray(data.formulas))
        {
          data.formulas.forEach((f) =>
          {
            if (f.icon && !f.icon.startsWith("assets/"))
            {
              f.icon = "assets/icons/" + f.icon;
            }
          });
        }

        // 2. Assign to state
        this.plants = data.plants || [];
        this.hermits = data.hermits || [];
        this.formulas = data.formulas || [];

        this.isLoading = false;
      }, 500); // Simulated delay
    },


  }//end method
  ,
  async mounted()
  {
    await this.waitForHerbsData();

  },
  async created()
  {

    this.isLoading = true;
    this.updateSearchCriteriaFromQuery = this.debounce(this.updateSearchCriteriaFromQuery, 500);

    await this.loadHerbsData();
    this.isLoading = false;

  }
};
</script>

