<template>
  <div
    class="flashcard"
    @click="handleCardClick"
  >
    <div
      class="flashcard-inner"
      :class="{ flipped }"
    >
      <div class="flashcard-front">
        <h2>{{ plant.name }}</h2>
        <div class="image-container">
          <!-- <img 
            :src="plant.image" 
            alt="plant Image" 
            :class="{ zoomed: isZoomed }" 
            @click.stop="handleImageClick" 
          />  -->
          <span
            v-if="!isZoomed"
            class="flip-icon"
            @click.stop="flipCard"
          >↩️</span>
        </div>
      </div>
      <div
        class="flashcard-back"
        @click="flipCard"
      >
        <button
          class="speak-button"
          @click.stop="speakPlantInfo"
        >🔊</button>
        <div class="text-container">
          <p class="part-item"><strong>ชื่อ:</strong>{{ plant.name }} ({{plant.page}},{{plant.type}})</p>
          <p
            v-for="(part, index) in plant.parts"
            :key="index"
            class="part-item"
          >
            <strong style="color:#581845">{{ part.part }}</strong>
            <span v-html="getTasteColor(part.taste)"></span>
            <span
              v-html="highlightBenefits(part.benefits)"
              color="#191970"
            ></span>
          </p>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import { colorDict } from "../utils/Util.js";
export default {

  props: {
    plant: Object,
    searchCriteria: Object,
    showBack: Boolean
  },
  watch: {
    showBack(newVal)
    {
      // Only update if different, so user flip isn't immediately overwritten
      if (this.flipped !== newVal)
      {
        this.flipped = newVal;
      }
    }

  },
  data()
  {
    return {
      flipped: false,
      isZoomed: false
    };
  },
  methods: {
    speakPlantInfo()
    {
      const { name, parts } = this.plant;
      let fullText = `ชื่อ ${name}. `;

      parts.forEach(part =>
      {
        const partName = part.part || '';
        const taste = part.taste ? `มีรส ${part.taste}` : '';
        const benefits = part.benefits?.length
          ? ` ${part.benefits.join(', ')}`
          : '';

        fullText += `${partName}, ${taste}, ${benefits}. `;
      });

      this.speakThai(fullText);
    },
    speakThai(text)
    {
      const msg = new SpeechSynthesisUtterance();
      msg.text = text;
      msg.lang = 'th-TH'; // Thai language
      msg.rate = 0.4;       // Speed (0.1 to 10)
      msg.pitch = 0.2;      // Pitch (0 to 2)
      msg.volume = 0.5;     // Volume (0 to 1)

      // Select Thai voice (optional)
      const voices = window.speechSynthesis.getVoices();
      const thaiVoice = voices.find(v => v.lang === 'th-TH');
      if (thaiVoice) msg.voice = thaiVoice;

      window.speechSynthesis.speak(msg);
    },
    handleCardClick()
    {
      if (this.flipped)
      {
        this.flipped = false;
      }
    },
    handleImageClick()
    {
      this.isZoomed = !this.isZoomed;
    },
    flipCard()
    {
      this.flipped = !this.flipped;
    },
    getTasteColor(text)
    {

      const key = Object.keys(colorDict).find(k => text.startsWith(k));
      var result = key ? colorDict[key] : "blue"; // Default color
      return `<span style="color: ${result}; font-weight: bold;"> (${text}) </span>`;
    },

    highlightBenefits(benefits)
    {
      const keyword = this.searchCriteria?.benefits?.trim().toLowerCase();

      if (!keyword || !Array.isArray(benefits))
      {
        return benefits.join(' ');
      }

      return benefits
        .map(benefit =>
        {
          if (benefit.toLowerCase().includes(keyword))
          {
            return `<span style="background-color: #420f02; color: white;">${benefit}</span>`;
          }
          return benefit;
        })
        .join(' ');
    }





  }
};
</script>
