<script>
import { getTasteColor, getFormattedTaste } from "../utils/Util.js";
import WarningDialog from './WarningDialog.vue';  // Adjust the path as necessary

export default {
  props: ["plants", "benefits", "icons"],
  components: {
    WarningDialog
  },
  data()
  {
    return {
      benefitDialog: false,
      benefitDialogData: [],
      filteredBenefits: [],
      searchQuery: '',
      searchCriteria: {
        name: "*",
        taste: "*",
        benefits: "*"
      },
      newBenefit: '',
      header_herbals: [
        { text: "ชื่อ", value: "name", width: "10%" },
        { text: "ส่วนสำคัญ", value: "parts", width: "70%" }
      ],
      editDialog: false,
      isNewPlant: false,
      selectedPlant: { name: "", parts: [] },
      warningDialog: false,  // Controls visibility of the dialog
      confirmDelete: false, //Controls visibility of confirm dialog
      warningMessage: "",  // The message to show in the dialog

    };
  },
  methods: {
    getTasteColor,
    getFormattedTaste,

    showBenefitDialog(benefits)
    {
      this.benefitDialogData = benefits;
      this.benefitDialog = true;
    },
    // Handle plant editing

    editPlant(plant)
    {
      this.isNewPlant = false; // <-- distinguish mode
      this.selectedPlant = JSON.parse(JSON.stringify(plant));
      this.editDialog = true;
    },

    // Add a new part to the selected plant
    addPart(part = "")
    {
      // Check if part already exists
      const partExists = this.selectedPlant.parts.some(p => p.part === part);

      if (partExists)
      {
        // Show the warning dialog if part exists
        this.warningMessage = `ส่วน '<b>${part}</b>' นี้มีอยู่แล้ว`; // Custom message
        this.warningDialog = true; // Open the dialog
      } else
      {
        // Add the part if it doesn't exist
        this.selectedPlant.parts.push({ part: part, taste: "", benefits: [] });

      }
    }
    ,


    // Remove a part from the selected plant
    removePart(index)
    {
      this.selectedPlant.parts.splice(index, 1);
    },

    createNewPlant()
    {
      this.isNewPlant = true;
      this.selectedPlant = { name: "", parts: [] };
      this.editDialog = true;
    },


    saveChanges()
    {
      if (this.isNewPlant)
      {
        //add check
        if (this.selectedPlant == null)
        {
          alert("no plant selected");
          return;
        }
        if (this.selectedPlant.name == "")
        {
          alert("please enter plant name");
          return;
        }
        if (this.selectedPlant.parts.length == 0)
        {
          alert("please enter at least 1 part");
          return;
        }


        // add to plants
        // eslint-disable-next-line vue/no-mutating-props
        this.plants.unshift(JSON.parse(JSON.stringify(this.selectedPlant)));
      } else
      {
        // edit existing
        const index = this.plants.findIndex(p => p.name === this.selectedPlant.name);
        if (index !== -1)
        {
          this.$set(this.plants, index, JSON.parse(JSON.stringify(this.selectedPlant)));
        }
      }
      this.editDialog = false;
    },

    getPartIcon(partName)
    {
      const partIcons = {
        'ราก': this.icons.parts.root,
        'เปลือก': this.icons.parts.bark,
        'ต้น': this.icons.parts.stem,
        'ใบ': this.icons.parts.leaf,
        'ดอก': this.icons.parts.flower,
        'ผล': this.icons.parts.fruit_durian,
        'ลูก': this.icons.parts.fruit_durian,
        'เมล็ด': this.icons.parts.seed,
        'กิ่ง': this.icons.parts.branch,
        'ยาง': this.icons.parts.latex,
        'เหง้า': this.icons.parts.rhizomes,

      };

      // Check for partial matches by searching for keywords in the partName
      for (const key in partIcons)
      {
        if (partName.includes(key))
        {
          return partIcons[key];
        }
      }

      // If no match is found, return the default icon
      return this.icons.parts.default;
    },

    //search functions
    updateSearchQuery()
    {
      const { name, taste, benefits } = this.searchCriteria;
      this.searchQuery = `${name !== "*" ? name : ""} ${taste !== "*" ? taste : ""} ${benefits !== "*" ? benefits : ""}`.trim();
    },
    updateSearchCriteriaFromQuery()
    {
      const queryParts = this.searchQuery.split(" ");
      this.searchCriteria.name = queryParts[0] || "*";
      this.searchCriteria.taste = queryParts[1] || "*";
      this.searchCriteria.benefits = queryParts[2] || "*";
    },
    clearSearch()
    {
      this.searchQuery = "";
      this.searchCriteria = { name: "*", taste: "*", benefits: "*" };
    },
    filterBenefits(searchText)
    {
      // Filter the benefits list based on the search text entered by the user
      if (searchText)
      {
        this.filteredBenefits = this.benefits.filter(benefit =>
          benefit.toLowerCase().includes(searchText.toLowerCase())
        );
      } else
      {
        this.filteredBenefits = [...this.benefits]; // Show all benefits when no search text
      }
    },
    // Remove a benefit from the part
    removeBenefit(partIndex, benefitIndex)
    {
      this.selectedPlant.parts[partIndex].benefits.splice(benefitIndex, 1);
    },
    handleBenefitSelection(partIndex, selectedBenefits)
    {
      const part = this.selectedPlant.parts[partIndex];
      // Iterate over each selected benefit in the array
      selectedBenefits.forEach(selectedBenefit =>
      {
        if (selectedBenefit && !this.benefits.includes(selectedBenefit))
        {
          // Add new benefit to both benefits and part.benefits if it doesn't already exist
          // eslint-disable-next-line vue/no-mutating-props
          this.benefits.push(selectedBenefit);

        }
      });
      // Ensure part.benefits is updated correctly with selected benefits
      part.benefits = selectedBenefits;
    },

    confirmRemovePlant(plant)
    {

      this.warningMessage = `คุณต้องการลบ "<b>${plant.name}</b>" ใช่หรือไม่?`;
      this.selectedPlant = plant;
      this.confirmDelete = true;

    },

    handleDelete()
    {



      if (this.selectedPlant && this.selectedPlant.name)
      {
        const index = this.plants.findIndex(p => p.name === this.selectedPlant.name);

        if (index !== -1)
        {


          // Reset selectedPlant and confirmDelete

          this.confirmDelete = false;
          // Notify parent about the deletion
          this.$emit('delete-plant', this.selectedPlant.name);
        } else
        {
          console.error("Plant not found in the list");
        }
      } else
      {
        console.error("No valid plant selected for deletion");
      }
    }



  }//end methods
  ,
  computed:
  {
    filteredItems()
    {
      const { name, taste, benefits } = this.searchCriteria;
      return this.plants.filter(item =>
      {
        const matchesName = (name === "*" || item.name.toLowerCase().includes(name.toLowerCase()));
        const matchesTasteAndBenefits = item.parts.some(part =>
        {
          const matchesTaste = (taste === "*" || part.taste.toLowerCase().includes(taste.toLowerCase()));
          const matchesBenefits = (benefits === "*" || part.benefits.some(benefit => benefit.toLowerCase().includes(benefits.toLowerCase())));
          return matchesTaste && matchesBenefits;
        });
        return matchesName && matchesTasteAndBenefits;
      });
    }
  },
  mounted()
  {
    // You can keep this for debugging, but currently no logic needed here
    this.filteredBenefits = [...this.benefits];
  }

};
</script>

