 <!-- eslint-disable vue/no-mutating-props -->
<!-- eslint-disable vue/valid-v-slot -->
<template>
    <v-container>
      <!-- Display Total Benefits Count -->
      <v-text-field
        label="Total Items"
        :value="benefits.length"
        readonly
        class="mb-4"
      />
  
      <!-- Search Box for Benefits -->
      <v-text-field
        v-model="searchQuery"
        label="Search Benefits"
        append-icon="mdi-magnify"
        clearable
        class="mb-4"
      />
  
      <!-- Benefits Table -->
      <v-data-table
        :items-per-page="itemsPerPage"
        :headers="headers"
        :items="benefits.map((text, index) => ({ id: index, benefit: text }))"
        item-key="id"
        class="elevation-1 black--text"
        no-data-text="No benefits found"
   :search="searchQuery"
      >
        <template v-slot:item.benefit="{ item }">
          <v-text-field
            v-model="benefits[item.id]"   
            label="Benefit"
            class="black--text"
            outlined
            dense
          />
        </template>
  
        <template v-slot:item.action="{ item }">
          <v-btn icon @click="removeBenefit(item.id)" color="red">
            <v-icon class="black--text">mdi-delete</v-icon>
          </v-btn>
        </template>
      </v-data-table>
  
      <!-- Add New Benefit Section -->
      <v-divider></v-divider>
      <v-text-field
        v-model="newBenefit"
        label="Add New Benefit"
        class="mt-4 black--text"
        append-icon="mdi-plus-circle"
        @keyup.enter="addBenefit"
      />
      <v-btn color="green" @click="addBenefit" class="mt-2 black--text">Add Benefit</v-btn>

        <!-- Warning Dialog -->
    <warning-dialog
      :isVisible="warningDialog"
      :message="warningMessage"
      :icon="icons.general.warning"
      @update:isVisible="warningDialog = $event"
    />
    </v-container>
  </template>
  
  <script>
  import WarningDialog from "./WarningDialog.vue"; // Adjust the path as needed

  export default {
    
    props: {
      icons:{
        type:Object,
        required: true
      },
      benefits: {
        type: Array,
        required: true
      },
    },
    components: {
    WarningDialog,
  },
    
    data() {
      return {
        warningDialog: false, // Controls warning dialog visibility
        warningMessage: "",
        searchQuery: "",
        newBenefit: "",
        itemsPerPage: 10,
        headers: [
          { text: "Benefit", align: "start", value: "benefit", class: "black--text" },
          { text: "Actions", align: "end", value: "action", class: "black--text" },
        ],
      };
    },
    methods: {
      addBenefit() {
      const trimmedBenefit = this.newBenefit.trim();

      if (!trimmedBenefit) return; // Ignore empty input

      if (this.benefits.includes(trimmedBenefit)) {
        // Show warning if the benefit already exists
        this.warningMessage = `สรรพคุณ '${trimmedBenefit}' มีอยู่แล้ว`;
        this.warningDialog = true;
      } else {
        // eslint-disable-next-line vue/no-mutating-props
        this.benefits.push(trimmedBenefit);
        this.newBenefit = "";
      }
    },
      removeBenefit(id) {
        // eslint-disable-next-line vue/no-mutating-props
        this.benefits.splice(id, 1); // Remove directly
      },
    },
  };
  </script>
  
  <style scoped>
  .v-data-table.black--text ::v-deep * {
    color: black !important;
  }
  
  .black--text input {
    color: black !important;
  }
  
  .v-data-table-header.black--text th {
    color: black !important;
  }
  </style>
  