<template>
    <div class="hermit-card" :class="{ flipped: isFlipped }" @click="handleCardClick">
      <!-- Front Side (Gallery) -->
      <div class="card-front">
        <div class="image-gallery">
          <img 
            v-for="(img, index) in hermit.images" 
            :key="index" 
            :src="img" 
            :alt="`Image ${index + 1}`" 
            :class="{ enlarged: enlargedImage === index }"
            @click="toggleImageSize(index, $event)"
          />
        </div>
      </div>
  
      <!-- Back Side (Details) -->
      <div class="card-back">
        <h2>{{ hermit.name }}</h2>
        <p><strong>สมุนไพร:</strong> {{ hermit.herb }}</p>
        <p><strong>ธาตุ:</strong> {{ hermit.element }}</p>
        <p><strong>ความเชื่อ:</strong> {{ hermit.believe }}</p>
      </div>
    </div>
</template>
  
<script>
  export default {
    props: ["hermit"],
    data() {
      return {
        isFlipped: false,
        enlargedImage: null, // Track which image is enlarged
      };
    },
    methods: {
      handleCardClick() {
        if (this.enlargedImage === null) {
          this.isFlipped = !this.isFlipped;
        }
      },
      toggleImageSize(index, event) {
        event.stopPropagation(); // Prevent flipping when clicking an image
        this.enlargedImage = this.enlargedImage === index ? null : index;
      }
    }
  };
</script>
  
  <style scoped>
  .hermit-card {
    width: 300px;
    height: 300px;
    perspective: 1000px;
    position: relative;
  }
  
  .card-front, .card-back {
    width: 100%;
    height: 100%;
    position: absolute;
    backface-visibility: hidden;
    border: 2px solid #ddd;
    border-radius: 10px;
    background: white;
